  if (rows == 1) {
    for (var row in precinctVotes) {
      if (row.isNotEmpty && row.contains(target[0])) return true;
    }
    return false;
  }

  int diagonalMin = rows + cols;
  int diagonalMax = rows - cols;

  Map<int, Set<int>> rowGroups = {};
  Map<int, Set<int>> colGroups = {};

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (precinctVotes[r][c] <= target[0]) {
        rowGroups.add(precinctVotes[r][c]);
