        colGroups.add(precinctVotes[r][c]);
        if (colGroups[precinctVotes[r][c]]!.length > 1) {
          return false;
        }
      }
    }
  }

  List<int> rowGroupsSorted = rowGroups.keys.toList()..sort();
  List<int> colGroupsSorted = colGroups.keys.toList()..sort();

  for (int targetRow in target) {
    for (int targetCol in target) {
      if (precinctVotes[targetRow][targetCol] <= target[0]) {
        bool found = false;
        for (int g in rowGroupsSorted) {
          if (precinctVotes[targetRow][targetCol] <= g && g <= target[0]) {
            found = true;
            break;
          }
        }
        if (!found) return false;
      }

      if (precinctVotes[targetRow][targetCol] >= target[1]) {
        bool found = false;
        for (int g in colGroupsSorted) {
          if (precinctVotes[targetRow][targetCol] >= g && g <= target[1]) {
            found = true;
            break;
          }
        }
        if (!found) return false;
      }
    }
  }

  int minDist = diagonalMin;
  int maxDist = diagonalMax;

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (precinctVotes[r][c] >= target[0] && precinctVotes[r][c] <= target[1]) {
        int dist = (r - target[0]).abs() + (c - target[1]).abs();
        if (dist < minDist) minDist = dist;
        if (dist > maxDist) maxDist = dist;
      }
    }
  }

