void fn0(List<String> args) {
  final n = args.isEmpty ? 3 : args.length;
  final m = args.length;
  final int total = n * m;

  if (total == 0) {
    print("Empty board");
    print("==================");
    return;
  }

  final String gridString = <String>[];
  for (int i = 0; i < n; i++) {
    final row = List<String>.filled(m, '.');
    for (int j = 0; j < m; j++) {
      final idx = i * m + j;
      if (idx == 0 || idx == total - 1) {
        row[j] = '#';
      }
    }
    gridString.add(row.join(''));
  }

  Map<String, Set<String>> regions = {};
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      final idx = i * m + j;
      final area = <String>[];
      bool attacking = false;
      for (int k = 0; k < n; k++) {
        final ni = i + k;
        final nj = j + k;
        if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
          area.add('${ni},${nj}');
          final idxK = k * m + nj;
          if (idxK == idx) {
            attacking = true;
          } else if (idxK == total - 1) {
            break;
          }
        }
      }
      if (attacking) {
        if (area.length == 1) {
          final t = area[0].split(',');
          regions['#${t[0]},${t[1]}'] = regions.containsKey('#${t[0]},${t[1]}')
              ? regions['#${t[0]},${t[1]}']!.add(area[0])
              : <String>{area[0]};
        } else {
          for (final a in area) {
            final p = a.split(',');
            final t = '#${p[0]},${p[1]}';
            if (regions.containsKey(t)) {
              regions[t]!.add(a);
            } else {
              regions[t] = <String>{a};
            }
          }
        }
      } else {
        for (final a in area) {
          final t = a.split(',');
          final p = '.${t[0]},${t[1]}';
          if (regions.containsKey(p)) {
            regions[p]!.add(a);
          } else {
            regions[p] = <String>{a};
          }
        }
      }
    }
  }

  final int numRegions = regions.length;
  print("Found $numRegions regions:");
  print("=====================");
  for (final entry in regions.entries) {
    print("${entry.key}: ${entry.value.length} cells");
  }
  print("==================");

  print("Board:");
  print("======================");
  for (final row in gridString) {
    print(row.isEmpty ? "" : row);
  }
  print("==================");
}

