  int _lengthOf(String s) {
    int len = 0;
    while (len < s.length && s[len] == s[s.length - 1 - len]) {
      len++;
    }
    return len;
  }

  bool _isPalindrome(String s) {
    final len = _lengthOf(s);
    if (len == 0) return true;
    final chars = s.split('');
    for (int i = 0; i < len ~/ 2; i++) {
      if (chars[i] != chars[len - 1 - i]) {
        return false;
      }
    }
    return true;
  }

  final palindromes = word.split('').fold<List<String>>([], (result, char) {
    final cleaned = char.toLowerCase().trim();
    if (_isPalindrome(cleaned)) {
      result.add(cleaned);
    }
    return result;
  });

  print(palindromes);
}

