  print('Frequency: $freq');
  print('Keys: $keys');

  int maxFreq = -1;
  String maxWord = '';

  for (String word in keys) {
    if (freq[word]! > maxFreq) {
      maxFreq = freq[word]!;
      maxWord = word;
    }
  }

