    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 9]
  ];

  int knightCount = 0;

  void search(List<List<bool>> visited, List<int> path, Set<int> visitedCells, List<List<int>> board) {
    if (path.length == board.length * board.length) {
      bool unique = path.toSet().length == board.length * board.length;
      if (unique) knightCount++;
      return;
    }

    int r = path[0] ~/ board.length;
    int c = path[0] % board.length;

    List<List<bool>> knightMoves = [
      [-2, -1], [-2, 1], [-1, -2], [-1, 2],
      [1, -2], [1, 2], [2, -1], [2, 1]
    ];

    for (var move in knightMoves) {
      int nr = r + move[0];
      int nc = c + move[1];

      if (nr >= 0 && nr < board.length && nc >= 0 && nc < board.length) {
        if (!visitedCells.contains(nr * board.length + nc)) {
          visited[nr][nc] = true;
          path.add(nr * board.length + nc);
          search(visited, path, visitedCells, board);
          path.removeLast();
          visited[nr][nc] = false;
        }
      }
    }
  }

  for (int r = 0; r < board.length; r++) {
    for (int c = 0; c < board.length; c++) {
      List<List<bool>> visited = List.generate(board.length, (_) => List.filled(board.length, false));

      List<int> path = [r * board.length + c];
      Set<int> visitedCells = {r * board.length + c};

      search(visited, path, visitedCells, board);

      for (int i = 0; i < board.length; i++) {
        String row = '';
        for (int j = 0; j < board.length; j++) {
          row += visited[i][j] ? '#' : '.';
        }
        print(row);
      }
    }
  }

  Map<int, List<int>> groups = {};

  for (int r = 0; r < board.length; r++) {
    for (int c = 0; c < board.length; c++) {
      String sq = '$r,$c';
      if (!groups.containsKey(sq)) {
        groups[sq] = [];
      }
    }
  }

  for (int r = 0; r < board.length; r++) {
    for (int c = 0; c < board.length; c++) {
      String sq = '$r,$c';
      groups[sq]!.add(r * board.length + c);
    }
  }

  print('Knights placed: $knightCount');
  print('Unique squares:');
  for (var entry in groups.entries) {
    print('${entry.key}: ${entry.value.length}');
  }
}

