Map<String, int> fn0(List<String> commands) {
  Map<String, int> counts = {
    '(': 0,
    ')': 0,
    '[': 0,
    ']': 0,
  };
  List<int> stack = [];
  List<String> history = [];

  int process(String cmd) {
    if (cmd == '(') {
      stack.add(0);
      counts['('] = counts['(']! + 1;
      history.add('(');
      return 0;
    }
    if (cmd == ')') {
      if (stack.isEmpty) return -1;
      int depth = stack.removeLast();
      int expected = counts[cmd]!;
      if (depth != expected) return -1;
      history.add(')');
      return 0;
    }
    if (cmd == '[') {
      stack.add(0);
      counts['['] = counts['[']! + 1;
      history.add('[');
      return 0;
    }
    if (cmd == ']') {
      if (stack.isEmpty) return -1;
      int depth = stack.removeLast();
      int expected = counts[cmd]!;
      if (depth != expected) return -1;
      history.add(']');
      return 0;
    }

    List<String> parts = cmd.split(',');
    int a = int.parse(parts[0]);
    int b = int.parse(parts[1]);
    int sum = a + b;
    String result = '$sum';

    if (result == '(' || result == ')' || result == '[' || result == ']') {
      stack.add(sum);
      counts[result] = counts[result]! + 1;
      history.add(result);
      return 0;
    }

    if (result == ')' || result == ']') {
      int depth = stack.removeLast();
      int expected = counts[result]!;
      if (depth != expected) return -1;
      history.add('$result');
      return 0;
    }

    int minLen = parts[2].length;
    for (int i = 3; i < parts.length; i++) {
      String token = parts[i];
      if (token.length < minLen) {
        minLen = token.length;
      }
    }

    int checksum = 0;
    for (int i = 0; i < minLen; i++) {
      checksum = (checksum + parts[i].codeUnitAt(i) * (i + 1)) % 97;
    }

    if (checksum == 0) {
      history.add('$result');
      return 0;
    }

    return checksum;
  }

  for (String cmd in commands) {
    if (process(cmd) != 0) {
      return counts;
    }
  }

  List<String> sorted = history.toList();
  sorted.sort();
  return {
    for (String s in sorted) s: counts[s]!
  };
}

