    int prev = current[name] ?? 0;
    int delta = count - prev;
    if (delta > 0) {
      current[name] = count;
    } else if (delta < 0) {
      current[name] = prev;
    }
    itemsSorted.add([name, count]);
  }
  itemsSorted.sort((a, b) => a[1] != b[1] ? a[1] - b[1] : a[0].compareTo(b[0]));
  List<String> result = [];
  void walk() {
    String top = '#';
    int threshold = itemsSorted[0][1];
    for (var entry in itemsSorted) {
      String item = entry[0];
      int count = entry[1];
      if (current[item]! >= threshold) {
        top = item;
        break;
      }
    }
    if (top == '#') top = '.';
    result.add(top);
    history.add('$top/${current[top]}');
  }
  walk();
  int total = 0;
  for (var entry in itemsSorted) {
    if (entry[1] <= current[entry[0]]!) total += entry[1];
  }
  while (total > 0) {
    walk();
    int newTotal = 0;
    for (var entry in itemsSorted) {
      if (entry[1] <= current[entry[0]]!) newTotal += entry[1];
    }
    total = newTotal;
  }
  return result;
}

