  List<int> freqArr = [];

  for (int i = 0; i < n; i++) {
    freq[data[i]] = (freq[data[i]] ?? 0) + 1;
    if (freq[data[i]] == 1) {
      freqArr.add(data[i]);
    }
  }

  if (freqArr.length < 2) {
    print('Invalid frequency pattern');
    return;
  }

  int minFreq = freqArr[0];
  int maxFreq = freqArr[0];
  List<int> freqMin = [];
  List<int> freqMax = [];

  for (int f in freqArr) {
    if (f < minFreq) minFreq = f;
    if (f > maxFreq) maxFreq = f;
    freqMin.add(minFreq);
    freqMax.add(maxFreq);
  }

  List<int> prefix = [];
  int runningSum = 0;

  for (int f in freqMin) {
    runningSum += f;
    prefix.add(runningSum);
  }

  int prefixLength = prefix.length;
  int k = prefixLength - 1;

  while (k > 0) {
    if (prefix[k] == maxFreq) {
      break;
    }
    k--;
  }

  int firstMaxIdx = k;
  int left = firstMaxIdx + 1;
  int right = prefixLength - 1;

  while (left <= right) {
    int mid = (left + right) ~/ 2;
    if (prefix[mid] <= maxFreq) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  int prefixFirstMaxIdx = left;
  int prefixMaxIdx = firstMaxIdx + (prefixLength - prefixFirstMaxIdx);

  int firstIdx = prefixMaxIdx % n;
  int maxIdx = prefixMaxIdx ~/ n;

  int minLen = 0;
  if (firstIdx > maxIdx) {
    minLen = firstIdx - maxIdx;
  } else {
    minLen = maxIdx - firstIdx;
  }

  print('Min length: $minLen');
  print('First occurrence: $firstIdx');
  print('Last occurrence: $maxIdx');
}

