void fn0() {



  List<String> args = List.tryParse(processArgs()) ?? [];

  if (args.isEmpty) {
    print('Usage: fn0 [option...] [amount]...');
    print('Option(s):');
    print('  -h     : Show this help message');
    print('  -v     : Show version number');
    print('  -a     : Show amount(s) in ascending order');
    print('  -d     : Show amount(s) in descending order');
    return;
  }

  String formatSign(int amount, String sign) {
    if (amount == 0) return '0';
    if (amount < 0) return '$sign0';
    return '$sign$amount';
  }

  List<int> amounts = [];
  for (String arg in args) {
    if (arg == '-h') {
      print('Usage: fn0 [option...] [amount]...');
      print('Option(s):');
      print('  -h     : Show this help message');
      print('  -v     : Show version number');
      print('  -a     : Show amount(s) in ascending order');
      print('  -d     : Show amount(s) in descending order');
      continue;
    }
    if (arg == '-v') {
      print('Version: 1.0.0');
      continue;
    }
    int? parsed = int.tryParse(arg);
    if (parsed == null || parsed < 0) {
      print('Invalid amount: $arg');
      continue;
    }
    amounts.add(parsed);
  }

  bool ascending = args.contains('-a');
  bool descending = args.contains('-d');

  if (amounts.isEmpty) {
    print('No valid amounts provided');
    return;
  }

  if (ascending || descending) {
    int minVal = amounts[0];
    int maxVal = amounts[0];
    for (int i = 1; i < amounts.length; i++) {
      if (amounts[i] < minVal) minVal = amounts[i];
      if (amounts[i] > maxVal) maxVal = amounts[i];
    }
    print('Min: ${formatSign(minVal, '-')}');
    print('Max: ${formatSign(maxVal, '+')}');
  }

  if (ascending) {
    List<int> sorted = List.from(amounts);
    sorted.sort();
    print('Ascending: ${sorted.toString()}');
  }

  if (descending) {
    List<int> sorted = List.from(amounts);
    sorted.sort((a, b) => b.compareTo(a));
    print('Descending: ${sorted.toString()}');
  }
}

