        Map<String, int> categoryFrequency = {};
        for (String category in prefix) {
          categoryFrequency[category] = (categoryFrequency[category] ?? 0) + 1;
        }
        categoryFrequency.forEach((category, count) {
          if (count > categoryCounts[category]!) {
            dp[i][j] = false;
            break;
          }
        });
      }
    }
  }

  int totalSubsets = 0;
  Map<String, int> categoryFrequency = {};
  for (int i = 0; i < n; i++) {
    for (int j = i; j < n; j++) {
      if (dp[i][j]) {
        totalSubsets++;
        List<String> subset = [];
        for (int k = i; k <= j; k++) {
          subset.add(categories[k]);
        }
        for (String category in subset) {
          categoryFrequency[category] = (categoryFrequency[category] ?? 0) + 1;
        }
      }
    }
  }

  print('Total subsets: $totalSubsets');
  categoryFrequency.forEach((category, count) {
    if (count > categoryCounts[category]!) {
      print('$category: ${count - categoryCounts[category]}');
    }
  });
}

