    'red': ['red', 'yellow'],
    'green': ['yellow', 'red'],
    'yellow': ['green', 'red'],
  };

  List<Set<String>> groups = [];

  Map<String, int> finalCounts = {
    'red': 0,
    'green': 0,
    'yellow': 0,
  };

