    List<String> path = [];
    void explore(String color) {
      if (!visited.contains(color)) {
        visited.add(color);
        path.add(color);
        String next = groupOrder[color]![0];
        if (next != null) {
          explore(next);
        } else {
          if (path.isNotEmpty) {
            String last = path.removeLast();
            counts[last] = counts[last]! + 1;
            finalCounts[last] = (finalCounts[last] ?? 0) + 1;
          }
        }
      }
    }

    for (String color in row) {
      if (!visited.contains(color)) {
        explore(color);
      }
    }
