  print('Final Counts: ${finalCounts}');

  bool allUnique = true;
  for (int i = 0; i < groups.length; i++) {
    Set<String> groupSet = groups[i];
    for (int j = 0; j < groups.length && j != i; j++) {
      if (groups[j].contains(groupSet.contains)) {
