List<String> fn0(String grid) {
  if (grid.isEmpty) return [];
  Set<String> rows = {};
  List<int> xs = [];
  List<int> ys = [];
  for (int i = 0; i < grid.length; i++) {
    String ch = grid[i];
    if (ch != '.' && ch != '#') continue;
    String key = '$ch$i';
    rows.add(key);
    xs.add(i);
    ys.add(ch == '#' ? -1 : i - 1);
  }
  if (rows.isEmpty) return [];

  List<String> results = [];
  Set<String> visited = {};
  List<int> current = [0, 0];
  List<String> history = [];
  bool solved = false;

  Set<String> queue = {};
  queue.add('$current${visited.isEmpty ? "" : ","}');
  visited.add('$current');

  while (!queue.isEmpty) {
    String move = queue.removeAt(0);
    history.add(move);
    List<String> parts = move.split(",");
    current = [int.parse(parts[0]), int.parse(parts[1])];
    String key = '${current[0]},${current[1]}';
    if (!visited.contains(key)) {
      visited.add(key);
      if (rows.contains(key)) {
        solved = true;
        break;
      }
    }

    for (int i = 0; i < xs.length; i++) {
      if (xs[i] == current[0] && ys[i] == current[1]) {
        String neighbor = '$current${visited.isEmpty ? "" : ","}';
        queue.add(neighbor);
        break;
      }
    }
  }

  if (!solved) {
    results.add("No solution found!");
  } else {
    results.add(history.reversed.join(" -> "));
    List<String> keys = rows.toList()..sort();
    List<List<int>> positions = [];
    for (int i = 0; i < keys.length; i++) {
      positions.add([keys[i], [xs[i], ys[i]]]);
    }
    positions.sort((a, b) {
      int dx = (a[1][0] - b[1][0]).abs();
      int dy = (a[1][1] - b[1][1]).abs();
      int manhattanA = dx + dy;
      int manhattanB = dx + dy;
      if (manhattanA != manhattanB) return manhattanA.compareTo(manhattanB);
      return a[0].compareTo(b[0]);
    });
    results.add("Positions:");
    for (var pos in positions) {
      results.add("${pos[0]}:${pos[1][0]},${pos[1][1]}");
    }
  }
  return results;
}

