    for (int j = 0; j < len; j++) {
      if (dp[n - 1][j]) {
        bestLen = len;
        bestFound = true;
        break;
      }
    }
    if (!bestFound) break;
    if (bestLen > maxLen) {
      maxLen = bestLen;
      patterns = [];
    }
    for (int j = 0; j < len; j++) {
      if (dp[n - 1][j]) {
        patterns.add(allPattern.substring(0, j + 1));
        break;
      }
    }
  }
  patterns.sort();
  return patterns;
}

