List<String> fn0(String log, int maxDiff) {
  List<String> matches = [];
  Set<String> seen = {};
  if (log.isEmpty) {
    return matches;
  }
  String? lastLevel;
  List<int>? lastTimes;
  for (int i = 0; i < log.length; i++) {
    String c = log[i];
    if (c == '<') {
      if (lastLevel != null) {
        matches.add('${lastLevel}-${lastTimes[0]}');
      }
      lastLevel = null;
      lastTimes = null;
    } else if (c == '|') {
      if (lastLevel != null) {
        matches.add('${lastLevel}-${lastTimes[0]}');
      }
      lastLevel = null;
      lastTimes = null;
    } else if (c == '[') {
      lastLevel = '';
      lastTimes = [];
    } else if (c == ']') {
      if (lastLevel != null && lastTimes != null) {
        matches.add('${lastLevel}-${lastTimes[0]}');
      }
      lastLevel = null;
      lastTimes = null;
    } else if (c == '-' && lastLevel != null && lastTimes != null) {
      int t1 = lastTimes[0];
      int t2 = int.parse(c);
      if (t2 - t1 <= maxDiff) {
        matches.add('${lastLevel}-${t1}');
      }
    } else if (c == '!') {
      if (lastLevel != null && lastTimes != null) {
        matches.add('${lastLevel}-${lastTimes[0]}');
      }
      lastLevel = null;
      lastTimes = null;
    } else if (c == ',') {
      if (lastLevel != null) {
        lastTimes.add(int.parse(c));
      }
    } else {
      if (c.length <= 4) {
        lastLevel = c;
        lastTimes = [c.length <= 2 ? int.parse(c) : int.parse(c[1])];
      }
    }
  }
  if (lastLevel != null && lastTimes != null) {
    matches.add('${lastLevel}-${lastTimes[0]}');
  }
  Set<String> deduped = {};
  for (String match in matches) {
    if (!seen.contains(match)) {
      seen.add(match);
      deduped.add(match);
    }
  }
  matches = deduped.toList();
  matches.sort();
  return matches;
}

