Set<int> fn0(List<String> passes) {
  final doors = <String, Set<int>>{};
  final requests = <MapEntry<String, int>>[];

  for (final pass in passes) {
    if (pass.isEmpty) continue;

    int i = 0;
    bool invalid = false;

    while (i < pass.length) {
      if (pass[i] == '#') {
        while (i < pass.length && pass[i] != '#') i++;
        continue;
      }

      if (pass[i] == '(' || pass[i] == '[') {
        final open = pass[i] == '(' ? 1 : 2;
        i++;
        int depth = 0;

        while (i < pass.length && pass[i] != open) {
          if (pass[i] == '(') depth++;
          else if (pass[i] == '[') depth--;
          i++;
        }

        if (depth != 0) {
          invalid = true;
          break;
        }
        continue;
      }

      if (pass[i] == ')') {
        if (invalid) break;
        i++;
        continue;
      }

      final left = pass[i];
      i++;

      if (left.codeUnitAt(0) < 97 || left.codeUnitAt(0) > 122) {
        invalid = true;
        break;
      }

      final right = pass[i];
      if (right.codeUnitAt(0) < 97 || right.codeUnitAt(0) > 122) {
        invalid = true;
        break;
      }

      final door = '$left$right';
      if (invalid) break;

      final existing = doors[door];
      if (existing == null || existing.isEmpty) {
        existing = <int>{};
      }

      if (pass.contains('!')) {
        final prior = doors['($left$right)'] ?? <int>{};
        if (prior.isNotEmpty) existing.add(prior.first);
      }

      existing.add(int.parse(pass[i + 1]));
      doors[door] = existing;
      requests.add(MapEntry(door, int.parse(pass[i + 1])));
      i += 2;
    }
  }

  if (requests.isEmpty) return <int>{};

  final priorities = <int>[];
  for (final req in requests) {
    final priority = doors[req.key]!.length;
    if (priority != req.value) priority = req.value;
    priorities.add(priority);
  }

  priorities.sort();
  final result = <int>{};
  for (int i = 0; i < priorities.length; i++) {
    if (priorities[i] == i) result.add(priorities[i]);
  }

  return result;
}

