void fn0(List<String> args) {
  if (args.isEmpty) {
    print('Usage: dart fn0.dart <input_file>');
    return;
  }

  String input = args[0];

  int maxCount = -1;
  String winner = '';
  List<String> rounds = [];

  List<String> parseRound(String round) {
    List<String> results = [];
    String token = '';

    for (int i = 0; i < round.length; i++) {
      String ch = round[i];
      if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
        token += ch;
      } else if (ch == '|' || ch == ' ') {
        if (token.isNotEmpty) {
          results.add(token);
          token = '';
        }
      } else {
        if (token.isNotEmpty && ch.codeUnitAt(0) >= 65 && ch.codeUnitAt(0) <= 90) {
          token += ch;
        }
      }
    }

    if (token.isNotEmpty) {
      results.add(token);
    }

    return results;
  }

  List<String> parseRounds(String roundsStr) {
    List<String> rounds = [];
    if (roundsStr.isEmpty) return rounds;

    List<String> parts = roundsStr.split(',');
    for (String part in parts) {
      List<String> tokens = parseRound(part);
      rounds.add(tokens.join('|'));
    }

    return rounds;
  }

  List<String> parseResults(String resultsStr) {
    List<String> results = [];
    if (resultsStr.isEmpty) return results;

    List<String> parts = resultsStr.split(',');
    for (String part in parts) {
      if (part.isNotEmpty) {
        results.add(part.trim());
      }
    }

    return results;
  }

  List<String> parseInputs(String inputsStr) {
    if (inputsStr.isEmpty) return [];

    List<String> parts = inputsStr.split(',');
    List<String> inputs = [];

    for (String part in parts) {
      if (part.isNotEmpty) {
        List<String> tokens = parseRound(part);
        if (tokens.length > 1) {
          for (String token in tokens) {
            int i = 0;
            while (i < token.length && token.codeUnitAt(i) >= 48 && token.codeUnitAt(i) <= 57) {
              i++;
            }
            if (i == token.length) {
              inputs.add(token);
            }
          }
        } else {
          inputs.add(tokens[0]);
        }
      }
    }

    return inputs;
  }

  List<String> parseSummary(String summaryStr) {
    List<String> lines = [];
    if (summaryStr.isEmpty) return lines;

    List<String> parts = summaryStr.split(',');
    for (String part in parts) {
      int hash = part.indexOf('#');
      if (hash > 0) {
        String header = part.substring(0, hash);
        String body = part.substring(hash + 1);
        if (header.isNotEmpty) {
          lines.add(header);
        }
        if (body.isNotEmpty) {
          lines.add(body);
        }
      }
    }

    return lines;
  }

  String parseData(String dataStr) {
    List<String> parsed = [];
    List<String> tokens = dataStr.split(',');
    for (String token in tokens) {
      int colon = token.indexOf(':');
      if (colon > 0 && colon < token.length - 1) {
        parsed.add(token.substring(0, colon) + ',' + token.substring(colon + 1));
      } else {
        parsed.add(token);
      }
    }

    return parsed.join(',');
  }

  List<String> parseTournament(String tournamentStr) {
    List<String> results = [];
    if (tournamentStr.isEmpty) return results;

    List<String> parts = tournamentStr.split('|');
    for (String part in parts) {
      if (part.isNotEmpty) {
        String token = part.trim();
        int colon = token.indexOf(':');
        if (colon > 0 && colon < token.length - 1) {
          String left = token.substring(0, colon);
          String right = token.substring(colon + 1);
          if (left.isNotEmpty && right.isNotEmpty) {
            results.add(left + ',' + right);
          }
        } else if (token.isNotEmpty) {
          results.add(token);
        }
      }
    }

    return results;
  }

  List<String> data = parseData(input);
  List<String> rounds = parseRounds(data);
  List<String> results = parseResults(data);
  List<String> inputs = parseInputs(data);
  List<String> summary = parseSummary(data);

  List<String> brackets = parseTournament(data);

  String bestName = '';
  int bestCount = -1;
  String bestSeed = '';
  int bestSeedCount = -1;

  for (String result in results) {
    int count = -1;
    String seed = '';
    String name = '';

    for (String round in rounds) {
      if (round.isEmpty) continue;

      List<String> tokens = round.split('|');
      for (String token in tokens) {
        if (token.isEmpty) continue;

        int colon = token.indexOf(':');
        if (colon > 0 && colon < token.length - 1) {
          String left = token.substring(0, colon);
          String right = token.substring(colon + 1);
          if (left.isNotEmpty && right.isNotEmpty) {
            String first = right.split(':')[0];
            if (first.isNotEmpty && first.contains(',')) {
              count = int.parse(first);
              break;
            }
          }
        } else if (token.isNotEmpty) {
          String first = token.split(':')[0];
          if (first.isNotEmpty && first.contains(',')) {
            seed = first;
            break;
          }
        }
      }

      if (count > 0 && seed.isNotEmpty) {
        break;
      }
    }

    if (count > 0 && seed.isNotEmpty) {
      if (count > bestCount || (count == bestCount && name.length < bestName.length)) {
        bestCount = count;
        bestName = name;
        bestSeed = seed;
      }
    }
  }

  print('Tournament: ${bestName} ($bestSeed)');
  print('Best: ${bestCount} seeds');
  print('Summary:');
  for (String line in summary) {
    print(line);
  }
  print('Inputs:');
  for (String input in inputs) {
    print(input);
  }
  print('Brackets:');
  for (String bracket in brackets) {
    print(bracket);
  }
}

@pragma('vm:never-inline')
