void fn0(List<String> args) {
  if (args.isEmpty) {
    print("Usage: dart fn0.dart <input>");
    print("Input is expected to be a log file with one entry per line.");
    print("The entry is a string of the form 'ip:port:delta', where:");
    print("  ip is the IP address of the client.");
    print("  port is the port number of the server.");
    print("  delta is the change in the port's value during the connection.");
    print("");
    print("The goal is to find the top 10 clients (by delta absolute value) "
        "who have made the most connections to servers with the largest "
        "absolute change in port (delta).");
    print("");
    return;
  }

  String file = args[0];

  if (file.isEmpty) {
    print("Usage: dart fn0.dart <input>");
    print("Input is expected to be a log file with one entry per line.");
    return;
  }

  print("File: $file");

  bool hasHeader = false;
  List<String> records = [];
  List<String> seen = [];

  List<String> splitLines(String line) {
    List<String> parts = line.split(';');
    for (int i = 0; i < parts.length; i++) {
      parts[i] = parts[i].trim();
    }
    return parts;
  }

  List<String> parse(String record) {
    if (record.isEmpty) {
      return [];
    }

    List<String> parts = splitLines(record);

    if (parts.length != 3) {
      print("Invalid entry: ${record.trim()}");
      return [];
    }

    String ip = parts[0].trim();
    String portStr = parts[1].trim();
    String deltaStr = parts[2].trim();

    if (ip.isEmpty || portStr.isEmpty || deltaStr.isEmpty) {
      print("Invalid entry: ${record.trim()}");
      return [];
    }

    int? port = int.tryParse(portStr);
    int? delta = int.tryParse(deltaStr);

    if (port == null || delta == null) {
      print("Invalid entry: ${record.trim()}");
      return [];
    }

    if (port <= 0 || delta <= 0) {
      print("Invalid entry: ${record.trim()}");
      return [];
    }

    return [ip, port, delta];
  }

  void processLine(String line) {
    if (line.isEmpty) {
      return;
    }

    List<String> parts = splitLines(line);

    if (parts.length != 3) {
      print("Invalid entry: ${line.trim()}");
      return;
    }

    String ip = parts[0].trim();
    String portStr = parts[1].trim();
    String deltaStr = parts[2].trim();

    if (ip.isEmpty || portStr.isEmpty || deltaStr.isEmpty) {
      print("Invalid entry: ${line.trim()}");
      return;
    }

    int? port = int.tryParse(portStr);
    int? delta = int.tryParse(deltaStr);

    if (port == null || delta == null) {
      print("Invalid entry: ${line.trim()}");
      return;
    }

    if (port <= 0 || delta <= 0) {
      print("Invalid entry: ${line.trim()}");
      return;
    }

    if (seen.contains(line)) {
      return;
    }
    seen.add(line);

    if (hasHeader) {
      print('|' + line.split(':')[0]);
    }

    int count = 0;
    for (int i = 0; i < records.length; i++) {
      List<String> recordParts = parse(records[i]);
      if (recordParts.isNotEmpty &&
          recordParts[0] == ip &&
          recordParts[1] == port) {
        count++;
      }
    }

    String out = '$ip:$port:$delta:$count';
    print(out);
