@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  if (args.isEmpty) {
    print('Usage: dart fn0.dart <file.csv>');
    return;
  }

  final csvFile = args[0];
  print(csvFile);

  var total = 0;
  var rows = 0;
  var cols = 0;
  var cells = 0;

  bool parse(String line) {
    final parts = line.split(',');
    if (parts.length != 4) return false;
    final r = int.parse(parts[0]);
    final c = int.parse(parts[1]);
    final v = int.parse(parts[3]);
    if (r < 0 || c < 0 || r > rows || c > cols || v < 0) return false;
    total += v;
    cells++;
    return true;
  }

  var seen = 0;

  for (var line in csvFile.split('\n')) {
    final trimmed = line.trim();
    if (trimmed.isEmpty) continue;

    var valid = true;
    for (var part in trimmed.split(',')) {
      final token = part.trim();
      if (token.isEmpty) {
        valid = false;
        break;
      }
    }

    if (!valid) continue;

    final parts = trimmed.split(',');
    final r = int.parse(parts[0]);
    final c = int.parse(parts[1]);
    final v = int.parse(parts[3]);

    if (v < 0) {
      valid = false;
      continue;
    }

    for (var r1 = 0; r1 < rows; r1++) {
      for (var c1 = 0; c1 < cols; c1++) {
        final r2 = r1 + r;
        final c2 = c1 + c;
        final dist = (r2 - r).abs() + (c2 - c).abs();
        if (dist > v) {
          seen++;
          break;
        }
      }
      if (seen > 0) break;
    }

    if (valid) {
      rows++;
      cols++;
    }
  }

  if (cells == 0) {
    print('No cells found in the CSV.');
    return;
  }

  print('Total: $total');
  print('Cells: $cells');
  print('Seen: $seen');
}

