Map<String, int> fn0(List<int> amounts, int unit) {
  if (amounts.isEmpty) return {};
  int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }
  int lcm(int a, int b) {
    int x = a ~/ gcd(a, b);
    int y = b ~/ gcd(a, b);
    return x * b;
  }
  int lcmAll(List<int> amounts) {
    if (amounts.length < 2) return 0;
    int result = lcm(amounts[0], amounts[1]);
    for (int i = 2; i < amounts.length; i++) {
      result = lcm(result, amounts[i]);
    }
    return result;
  }
  int sumOfLcm(List<int> amounts) {
    int total = 0;
    for (int i = 0; i < amounts.length; i++) {
      total += lcm(unit, amounts[i]);
    }
    return total;
  }
  int gcfOfSums(List<int> amounts) {
    int sumA = 0;
    int sumB = 0;
    for (int i = 0; i < amounts.length; i++) {
      sumA += lcm(unit, amounts[i]);
    }
    for (int i = 0; i < amounts.length; i++) {
      sumB += amounts[i];
    }
    return gcd(sumA, sumB);
  }
  Map<String, int> result = {
    'lcmAll': lcmAll(amounts),
    'sumOfLcm': sumOfLcm(amounts),
    'gcfOfSums': gcfOfSums(amounts),
  };
  for (String key in result.keys) {
    int value = result[key]!;
    if (value.isOdd) {
      result[key] = value - 1;
    } else if (value.isEven && (value & 2) == 0) {
