double fn0(List<int> deck) {
  if (deck.length < 2) {
    return 0.0;
  }
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }
  int g = deck[0];
  for (int i = 1; i < deck.length; i++) {
    g = gcd(g, deck[i]);
  }
  if (g == 0) {
    return 0.0;
  }
  int total = 0;
  for (int i = 0; i < deck.length; i++) {
    total += deck[i] ~/ g;
  }
  return total / deck.length;
}

