      ['N00', 0],
      ['N01', 1],
      ['N02', 2],
      ['N03', 3],
    ],
  };

  Set<int> uniqueValues = {
    cellValues['N00']!,
    cellValues['N01']!,
    cellValues['N02']!,
    cellValues['N03']!,
    cellValues['N04']!,
  };

  for (var state in uniqueValues) {
    bool isLeaf = true;
