bool fn0(String password) {
  int n = password.length;
  if (n < 8) return false;
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    if (i == 1) dp[i] = 1;
    else {
      int j = i - 1;
      dp[i] = dp[j];
      if (j > 0) {
        int l = password.codeUnitAt(j - 1) % 10;
        int r = password.codeUnitAt(i - 1) % 10;
        if ((l == r || (l + r) % 2 == 0)) dp[i]++;
      }
    }
  }
  return dp[n] >= 9;
}

