      rows.add(row);
    }
  }

  print('Password:');
  print('-------');
  do {
    line = '';
    bool valid = true;
    print('?');

    for (int i = 0; i < 8; i++) {
      String ch = line;
      if (i < line.length) {
        ch += line[i];
      }
      print('$ch');
    }

