    for (int r = 0; r < rows; r++) {
      String row = grid.substring(r * 9, r * 9 + 9);
      print(row);
    }
  }

  List<String> solveSudoku(String grid) {

    List<String> solutions = [];
    bool hasUniqueEmpty = false;

    for (int i = 0; i < grid.length; i++) {
      if (grid[i] == '.') {
        hasUniqueEmpty = true;
        break;
      }
    }

    if (!hasUniqueEmpty) {
      solutions.add(grid);
      return solutions;
    }

    void check(int r, int c, String num) {
      if (num.length < 9) return;
      String row = grid.substring(r * 9, r * 9 + 9);
      String col = row.substring(c, c + 9);
      String box = '';
      for (int s = 0; s < 9; s++) {
        box += row[s];
        box += col[s];
      }

      List<String> nums = [];
      for (int s = 0; s < 9; s++) {
        nums.add(box[s]);
      }

      List<int> counts = List.filled(9, 0);
      for (String n in nums) {
        counts[n.codeUnitAt(0) - 48]++;
      }

      bool valid = true;
      for (int v in counts) {
        if (v > 1) {
          valid = false;
          break;
        }
      }

      if (!valid) return;

      List<String> dirs = [
        if (r > 0) row.substring(0, c) + row.substring(c + 9),
        if (r < 8) row.substring(c) + row.substring(0, c),
        if (c > 0) col.substring(0, r) + col.substring(r + 9),
        if (c < 8) col.substring(r) + col.substring(0, r),
      ];

      for (String dir in dirs) {
        if (!dir.contains(num)) {
          return;
        }
      }

      solutions.add(dir);
    }

    for (int r = 0; r < 9; r++) {
      for (int c = 0; c < 9; c++) {
        if (grid[r * 9 + c] != '.') {
          continue;
        }

        for (int d = 0; d < 9; d++) {
          String num = (d + 1).toString();
          if (num.length < 2) {
            num = '0' + num;
          }

          check(r, c, num);
        }
      }
    }

    return solutions;
  }

  String grid = '''
  ...
  ...
  ...
  ...
  ...
  ...
  ...
  ...
  ...
  ''';

  List<String> solutions = solveSudoku(grid);
  print('Possible Solutions:');
  for (String s in solutions) {
    printGrid(s);
  }
}

