Map<String, int> fn0(List<int> signals, int threshold) {
  if (signals.isEmpty) return {'red': 0, 'yellow': 0, 'green': 0};
  int n = signals.length;
  List<int> dp0 = List.filled(n + 1, 0);
  List<int> dp1 = List.filled(n + 1, 0);
  List<int> dp2 = List.filled(n + 1, 0);

  dp0[0] = 1;
  dp1[0] = 0;
  dp2[0] = 0;

  for (int i = 1; i <= n; i++) {
    for (int j = i - 1; j >= 0 && signals[j] >= threshold; j--) {
      int prev = dp1[j];
      dp0[i] = dp0[i] + prev;
      dp1[i] = dp1[i] + (signals[i - 1] >= threshold ? prev : 0);
      dp2[i] = dp2[i] + (signals[i - 1] >= threshold ? dp1[i - 1] : dp0[i - 1]);
    }
  }

  return {'red': dp0[n], 'yellow': dp1[n], 'green': dp2[n]};
}

