Map<String, int> fn0(List<int> heights) {
  if (heights.isEmpty) return {'area': 0, 'perimeter': 0};
  int n = heights.length;
  List<int> dp = List.filled(n + 1, 0);
  List<int> prefix = List.filled(n + 1, 0);
  List<int> sum = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    int lo = 0, hi = i - 1;
    while (lo < hi) {
      int mid = (lo + hi) >> 1;
      if (heights[mid] <= heights[i - 1]) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    prefix[i] = lo;
  }
  for (int i = 1; i <= n; i++) {
    sum[i] = sum[i - 1] + heights[i - 1] + heights[i - 1] - heights[prefix[i] - 1];
  }
  int area = sum[n];
  int perimeter = 0;
  for (int i = 1; i <= n; i++) {
    if (heights[i - 1] >= 0) {
      perimeter += 2 * heights[i - 1] - heights[prefix[i] - 1];
    }
  }
  return {'area': area, 'perimeter': perimeter};
}

