@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  Map<String, Object> result = {};

  void process(String path, int depth, List<String> visited, Map<String, Object> parent) {
    if (path.isEmpty) {
      result[path] = 1;
      return;
    }

    List<String> parts = path.split('/');
    String fileName = parts.last;

    bool isDirectory = parts.length > 1;
    bool containsFile = false;

    for (String part in parts) {
      if (part.isEmpty) continue;
      bool valid = int.tryParse(part) != null;

      if (valid && !containsFile) {
        containsFile = true;
      }
    }

    if (!containsFile) {
      isDirectory = true;
    }

    if (isDirectory) {
      for (String dir in parts.sublist(0, parts.length - 1)) {
        String fullDir = '$path/$dir';
        parent[fullDir] = true;
        process(fullDir, depth + 1, visited, parent);
      }
    } else {
      if (!visited.contains(fileName)) {
        visited.add(fileName);
        result['$path/$fileName'] = (result['$path/$fileName'] ?? 0) + 1;
      }
    }
  }

  if (args.length >= 2) {
    String startPath = args[0];
    String targetPath = args[1];

    Map<String, Object> parent = {};
    parent[startPath] = true;

    List<String> visited = [];

    process(startPath, 0, visited, parent);

    bool found = false;

    for (String path in result.keys) {
      if (path.contains(targetPath)) {
        print('$path: ${result[path]}');
        found = true;
        break;
      }
    }

    if (!found) {
      print('$targetPath not found in $startPath');
    }
  } else {
    print('Usage: $startPath/$targetPath');
  }
}

