void fn0(List<String> args) {
  if (args.isEmpty) {
    print('Usage: dart fn0.dart <file.txt>');
    return;
  }

  final file = args[0];
  final wordCounts = <String, int>{};

  void countWords(String line) {
    final parts = line.split(' ');
    for (var word in parts) {
      final normalized = word.isEmpty ? '' : word[0].toUpperCase() + word.substring(1);
      wordCounts[normalized] = (wordCounts[normalized] ?? 0) + 1;
    }
  }

  final lines = <String>[];
  int i = 0;
  while (i < file.length) {
    final j = i;
    while (j < file.length && file[j] == file[i]) {
      j++;
    }
    lines.add(file.substring(i, j));
    i = j;
  }

  for (final line in lines) {
    countWords(line);
  }

  print(wordCounts);
}

