void fn0(List<String> args) {

  if (args.isEmpty) {
    print('Usage: dart fn0.dart [seed] [depth]');
    print('Where [seed] is the initial weight, [depth] is the search depth.');
    print('A larger [depth] means a more extensive search.');
    print('The program will print a search tree of the given depth.');
    print('Each node represents a search state, with [seed] as the weight.');
    print('The tree is displayed as a binary tree with " / " as the separator.');
    return;
  }

  final seed = int.tryParse(args[0]);
  if (seed == null || seed < 0) {
    print('Invalid seed value.');
    return;
  }

  final depth = args.length >= 2
      ? int.tryParse(args[1])
      : 2; 

  if (depth < 0 || depth > 64) {
    print('Invalid search depth.');
    return;
  }

  final Map<String, BigInt> counts = {
    'max': BigInt.minPositive(),
    'min': BigInt.maxPositive(),
    'avg': BigInt.zero()
  };

  void search(int depth, int node) {
    if (depth == 0) {

      counts['max'] = BigInt.max(counts['max']!, seed);
      counts['min'] = BigInt.min(counts['min']!, seed);
      counts['avg'] = BigInt.sum(counts['avg']!, seed) / BigInt.from(2);
    } else {

      final int left = node * 2;
      final int right = left + 1;
      search(depth - 1, left);
      search(depth - 1, right);
    }
  }

  print('Search Tree of Depth $depth:');
  search(depth, 0);
  print('Max: ${counts['max']}');
  print('Min: ${counts['min']}');
  print('Avg: ${counts['avg']}');
}

