    List<String> parts = code.split(',');
    List<int> runs = parts.map((part) {
      List<String> pairs = part.split('');
      int sum = 0;
      for (int i = 0; i < pairs.length; i += 2) {
        sum += (pairs.codeUnitAt(i) - 48) * (pairs.codeUnitAt(i + 1) - 48);
      }
      return sum;
    }).toList();
    return runs.map((r) => String.fromCharCode(r)).join();
  }

