  String key(int x, int y) => '$x,$y';

  void printMap(Map<String, int> m, String name) {
    print('------------------------------');
    print('$name:');
    for (int y = n - 1; y >= 0; y--) {
      String line = '';
      for (int x = 0; x < n; x++) {
        line += m[key(x, y)] == null ? ' ' : m[key(x, y)]!;
      }
      print(line);
    }
    print('------------------------------');
  }

  int solve(int r, int c, List<String> maze) {
    int h = maze.length;
    int w = maze[0].length;

    String key = '';
    for (int i = 0; i < h; i++) {
      for (int j = 0; j < w; j++) {
        key += maze[i][j];
      }
    }

    Map<String, int> prev = {};
    int best = INF;

    for (int x = 0; x < n; x++) {
      for (int y = 0; y < n; y++) {
        String key = '$x,$y';
        if (prev.containsKey(key)) {
          prev[key] = 0;
        }
      }
    }

    for (int r = 0; r < h; r++) {
      for (int c = 0; c < w; c++) {
        if (maze[r][c] == '#') continue;

        String key = '$r,$c';
        if (prev.containsKey(key)) {
          int value = prev[key]!;
          if (value <= 1) {
            prev[key] = 0;
          } else if (value < best) {
            best = value;
          }
        }

        for (int d = 0; d < 4; d++) {
          int nr = r + dy[d];
          int nc = c + dx[d];

          if (nr >= 0 && nr < h && nc >= 0 && nc < w && maze[nr][nc] != '#') {
            String nextKey = '$nr,$nc';
            if (!prev.containsKey(nextKey)) {
              int cost = 1;
              if (d == 0) {
                cost = 2;
              } else if (d == 1) {
                cost = 4;
              } else if (d == 2) {
                cost = 8;
              } else if (d == 3) {
                cost = 16;
              }

              prev[nextKey] = cost;
            }
          }
        }
      }
    }

    return best;
  }

  void solveMaze(List<String> maze) {
    int total = 0;

    for (int r = 0; r < maze.length; r++) {
      for (int c = 0; c < maze[r].length; c++) {
        if (maze[r][c] == '#') continue;
        String key = '$r,$c';
        if (dp.containsKey(key)) {
          total += dp[key]!;
        }

        for (int d = 0; d < 4; d++) {
          int nr = r + dy[d];
          int nc = c + dx[d];

          if (nr >= 0 && nr < maze.length && nc >= 0 && nc < maze[nr].length && maze[nr][nc] != '#') {
            String nextKey = '$nr,$nc';
            if (!dp.containsKey(nextKey)) {
              dp[nextKey] = solve(nr, nc, maze);
            }
            total += dp[nextKey]!;
          }
        }
      }
    }

    printMap(dp, 'dp');
    print('Total: $total');
  }

  void printBoard(List<String> maze) {
    for (int r = 0; r < maze.length; r++) {
      String line = '';
      for (int c = 0; c < maze[r].length; c++) {
        line += maze[r][c];
      }
      print(line);
    }
  }

  List<String> maze1 = [
    '#.#..#',
    '#....#',
    '#....#',
    '#....#',
  ];
  List<String> maze2 = [
    '#..#.',
    '.#...',
    '#..#.',
    '.#...',
  ];

  printBoard(maze1);
  solveMaze(maze1);
  printBoard(maze1);

  printBoard(maze2);
  solveMaze(maze2);
  printBoard(maze2);
}

