    0x0D, 0x19, 0x13, 0x3D, 0x3B, 0x37, 0x0B, 0x31, 0x33, 0x35, 0x23, 0x2F, 0x3E, 0x3A,
  ];

  void search(String row, int rowIdx, int colIdx, int mask) {
    if (rowIdx == rows && colIdx == cols) {
      if (mask == 0) {
        String key = '${row.padRight(cols, '0')}|${mask.toRadixString(16).padLeft(16, '0')}|${(bestLengths['0000000000000000'] ?? 0)}';
        if (!bestLengths.containsKey(key)) {
          bestLengths[key] = (bestLengths[key] ?? 0) + 1;
        }
        return;
      }
      return;
    }
    int newMask = mask & 0xFFFFFFFF;
    if ((mask & 0x3F) == 0) {
      newMask &= 0x0D;
    }
    if ((mask & 0x3B) == 0) {
      newMask |= 0x19;
    }
    if ((mask & 0x37) == 0) {
      newMask ^= 0x13;
