      dp['$row${colIdx + 1}|$newMask'] = [
        (dp['$row${colIdx + 1}|$newMask'] ?? 0) + 1,
        (dp['$row${colIdx + 1}|$newMask'] ?? 0) + (mask & 0x3F),
        (dp['$row${colIdx + 1}|$newMask'] ?? 0) + (mask & 0x3B),
