        (dp['$row${colIdx + 1}|$newMask'] ?? 0) + (mask & 0x3E),
        (dp['$row${colIdx + 1}|$newMask'] ?? 0) + (mask & 0x2F),
        (dp['$row${colIdx + 1}|$newMask'] ?? 0) + (mask & 0x3A),
      ];
    }
    search(row + data[rowIdx][colIdx], rowIdx + 1, colIdx + 1, newMask);
