      }
    }
  }

  int bestLen = 0;
  String bestRow = '';
  String bestCol = '';
  String bestMask = '0000000000000000';

  dp[bestMask] = [0, 0, 0, 0, 0, 0, 0, 0];
  for (String key in dp.keys) {
    int len = key.split('|').length - 1;
    if (len > bestLen) {
      bestLen = len;
      bestMask = key;
      bestRow = key.split('|')[0];
      bestCol = key.split('|')[1];
    } else if (len == bestLen && dp[key][0] > dp[bestMask][0]) {
      bestMask = key;
      bestRow = key.split('|')[0];
      bestCol = key.split('|')[1];
    }
  }

  int score = bestLen * 2;
  if (bestLen == minLength) {
    score += 2;
  } else if (bestLen < minLength) {
    score += 1;
  }
  if ((bestMask & 0x3F) == 0) {
    score += 1;
  }
  print('Row: $bestRow');
  print('Col: $bestCol');
  print('Mask: ${bestMask.padRight(16, '0')}');
  print('Length: $bestLen');
  print('Score: $score');
}

import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final int n = 3;

  const List<List<int>> directions = [
    [-2, -1],
    [-2, 1],
    [-1, -2],
    [-1, 2],
    [1, -2],
    [1, 2],
    [2, -1],
    [2, 1]
  ];

  final List<List<int>> grid = List.generate(n, (_) => List.filled(n, 0));

  const int mask = 13;

  int countFlags(int cell) {
    int count = 0;
    for (int i = 0; i < 4; i++) {
      if (((cell >> i) & 1) == 1) count++;
    }
    return count;
  }

  bool isClear(int cell) {
    return (cell & mask) == 0;
  }

  void printGrid() {
    for (var row in grid) {
      String line = '';
      for (var val in row) {
        line += val.toString().padRight(2);
      }
      print(line);
    }
    print('');
  }

  int nCr(int n, int r) {
    if (r > n) return 0;
    if (r == 0 || r == n) return 1;
    int num = 1;
    int den = 1;
    for (int i = 0; i < r; i++) {
      num = (num * (n - i)) ~/ (i + 1);
      den = (den * (r - i)) ~/ (i + 1);
    }
    return num ~/ den;
  }

  void solve() {

    Map<String, int> totalPop = {};
    Map<String, Map<String, int>> subPop = {};
    Map<String, Map<String, int>> subFreq = {};
    Map<String, int> subPopCount = {};
    Map<String, Map<String, List<int>>> subFreqRows = {};

    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        String key = '$i,$j';
        totalPop[key] = (totalPop[key] ?? 0) + 1;
        subPop.containsKey(key)
            ? subPop[key]![key] = (subPop[key]![key] ?? 0) + 1
            : subPop[key] = {key: 1};
      }
    }

    for (String key in totalPop.keys) {
      int row = key[0];
      int col = key[1];
      String subKey = '$row,$col';
      subFreq[subKey] = (subFreq[subKey] ?? {});
      subFreq[subKey]![key] = (subFreq[subKey]![key] ?? 0) + 1;
      subPopCount[subKey] = (subPopCount[subKey] ?? 0) + 1;
    }

    int maxSubPop = -1;
    String bestSub = '';
    int bestSubCount = 0;

    for (String subKey in subPop.keys) {
      int subCount = subPop[subKey]!.length;
      if (subCount > maxSubPop ||
          (subCount == maxSubPop && subPopCount[subKey]! > bestSubCount) ||
          (subCount == maxSubPop && subPopCount[subKey]! == bestSubCount)) {
        maxSubPop = subCount;
        bestSub = subKey;
        bestSubCount = subPopCount[subKey]!;
      }
    }

    String subKey = bestSub;
    Map<String, List<int>> subFreqRows = subFreqRows[subKey] ?? {};

    for (String key in subFreq[subKey]!.keys) {
      int row = key[0];
      int col = key[1];
      subFreqRows[key] = (subFreqRows[key] ?? []) + [row, col];
    }

    StringBuffer sb = StringBuffer();
    sb.write('$bestSub:$bestSubCount\n');
    subFreqRows.forEach((key, rows) {
      int rowSum = rows.fold(0, (a, b) => a + b);
      sb.write('$key:${rowSum.padRight(2)} ');
    });
    print(sb.toString());
  }

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      String cellKey = '$i,$j';
      if (isClear(cellKey)) {
        for (var dir in directions) {
          int ni = i + dir[0];
          int nj = j + dir[1];
          if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
            String subKey = '$ni,$nj';
            subFreq[subKey] = (subFreq[subKey] ?? {});
            subFreq[subKey]![cellKey] = (subFreq[subKey]![cellKey] ?? 0) + 1;
          }
        }
      }
    }
  }

  printGrid();

  int clearCount = 0;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (isClear('$i,$j')) {
        clearCount++;
      }
    }
  }

  print('Total Clear Cells: $clearCount');
  print('Total Sub-Populations: ${totalPop.length}');

  solve();
}

