  const int total = N * N;

  final positions = <int>{};
  for (int i = 0; i < total; i++) {
    positions.add(i);
  }

  final Map<int, Set<int>> rowEdges = {};
  for (int r = 0; r < N; r++) {
    for (int c = 0; c < N; c++) {

      final int idx = r * N + c;
      if (r > 0) {
        rowEdges.putIfAbsent(idx, () => positions).add(idx - 1);
      }
      if (r < N - 1) {
        rowEdges.putIfAbsent(idx, () => positions).add(idx + 1);
      }
    }
  }

  final Map<int, Set<int>> colEdges = {};
  for (int c = 0; c < N; c++) {
    for (int r = 0; r < N; r++) {

      final int idx = r * N + c;
      if (c > 0) {
        colEdges.putIfAbsent(idx, () => positions).add(idx - N);
      }
      if (c < N - 1) {
        colEdges.putIfAbsent(idx, () => positions).add(idx + N);
      }
    }
  }

  const int dirs = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  final Map<int, int> rowEdgeCounts = {};
  final Map<int, int> colEdgeCounts = {};

  void dfs(int idx, Set<int> visited) {
    if (visited.contains(idx)) return;
    visited.add(idx);

    if (idx >= 0 && idx < total) {

      rowEdgeCounts[idx] = (rowEdgeCounts[idx] ?? 0) + 1;
    }

    for (final d in dirs) {
      final int neighbor = idx + d[0];
      if (neighbor >= 0 && neighbor < total) {
        dfs(neighbor, visited);
      }
    }
  }

  for (int idx = 0; idx < total; idx++) {
    if (idx >= 0 && idx < total) {
      final Set<int> visited = {};
      dfs(idx, visited);

      if (idx.isEven) {
        colEdgeCounts[idx] = rowEdgeCounts[idx]!;
      } else {
        colEdgeCounts[idx] = rowEdgeCounts[idx]!;
      }
    }
  }

  final List<String> rows = [
    for (int r = 0; r < N; r++)
      [for (int c = 0; c < N; c++)
        if ((r == 0 || c == 0) || (r == N - 1 || c == N - 1))
          '$r,$c',
  ];

  final List<List<int>> rects = [];
  for (final entry in rowEdges.entries) {
    if (entry.value.length == 2) {
      rects.add([entry.key, entry.value.toList()..sort()]);
    }
  }

  rects.sort((a, b) {
    if (a[1][0] != b[1][0]) return a[1][0].compareTo(b[1][0]);
    if (a[1][1] != b[1][1]) return a[1][1].compareTo(b[1][1]);
    return a[0].compareTo(b[0]);
  });

  final List<List<int>> cols = [];
  for (final entry in colEdges.entries) {
    if (entry.value.length == 2) {
      cols.add([entry.key, entry.value.toList()..sort()]);
    }
  }

  cols.sort((a, b) {
    if (a[1][0] != b[1][0]) return a[1][0].compareTo(b[1][0]);
    if (a[1][1] != b[1][1]) return a[1][1].compareTo(b[1][1]);
    return a[0].compareTo(b[0]);
  });

  print(rects);
  print(cols);
}

