    return;
  }

  Set<int> shared = {};

  for (var w in winners) {
    for (var v in votes) {
      if (valid[v]! >= w && v != w) {
        shared.add(v);
        break;
      }
    }
  }

  if (shared.isEmpty) {
    print('No shared votes between candidates');
    return;
  }

  Map<int, int> counts = {};

  for (var v in shared) {
    counts[v] = (counts[v] ?? 0) + 1;
  }

  List<String> parts = [];

  for (var entry in counts.entries) {
    parts.add('${entry.key}*${entry.value}');
  }

  parts.sort();

  print('Shared votes: ${parts.join(', ')}');
}

