void fn0() {

  List<int> sorted = [1, 3, 5, 7, 9, 11];

  List<int> generatePermutations(List<int> sorted) {

    Set<int> usedIndices = {};
    for (int i = 0; i < sorted.length; i++) usedIndices.add(i);

    List<List<int>> permutations = [];

    void backtrack(List<int> current, List<bool> used) {
      if (current.length == sorted.length) {
        permutations.add(current);
        return;
      }

      for (int i = 0; i < sorted.length; i++) {
        if (!used[i]) {

            used[i] = true;
            current.add(sorted[i]);
            backtrack(current, used);
            current.removeLast();
            used[i] = false;
        }
      }
    }

    List<bool> used = List.filled(sorted.length, false);
    backtrack([], used);

    return permutations;
  }

  Map<int, int> freq = {};
  for (int value in sorted) {
    freq[value] = (freq[value] ?? 0) + 1;
  }

  List<List<int>> freqPermutations = [];
  for (var entry in freq.entries) {
    List<int> freqSorted = entry.value.toList()..sort();
    freqPermutations.add(generatePermutations(freqSorted));
  }

  int maxFreq = 0;
  int topCount = 0;
  for (var pf in freqPermutations) {
    int f = pf[0];
    if (f > maxFreq) {
      maxFreq = f;
      topCount = 1;
    } else if (f == maxFreq) {
      topCount++;
    }
  }

  List<List<int>> topPermutations = freqPermutations.where((pf) => pf[0] == maxFreq).toList();
  topPermutations.sort((a, b) => a[0].compareTo(b[0]));

  print('Top $topCount permutations with frequency $maxFreq or more:');
  for (int i = 0; i < topPermutations.length; i++) {
    List<int> pf = topPermutations[i];
    print('${i + 1}: ${pf.join(", ")}');
  }
}

