void fn0() {
  List<int> arr = [1, 2, 3, 4, 5, 6, 7];
  int n = arr.length;

  List<List<int>> dp = List.generate(
    n + 1,
    (_) => List.filled(n + 1, 0),
  );

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= n - i; j++) {
      int endIdx = j + i;
      int targetSum = i * (j + 1);
      bool found = false;

      for (int k = 0; k < i; k++) {
        int partialSum = k * (j + 1) + (i - k) * (endIdx - j);
        if (partialSum == targetSum) {
          dp[i][j] = 1;
          found = true;
          break;
        } else if (partialSum < targetSum) {
          break;
        }
      }

      if (!found) {
        dp[i][j] = 0;
      }
    }
  }

  List<List<int>> partialSumArr = List.generate(
    n + 1,
    (_) => List.filled(n + 1, 0),
  );

  List<List<String>> result = List.generate(
    n + 1,
    (_) => List.filled(n + 1, ''),
  );

  List<List<int>> path = List.generate(
    n + 1,
    (_) => List.filled(n + 1, 0),
  );

  void solve(int i, int j) {
    if (i == n + 1) {
      return;
    }

    if (dp[i][j] == 1) {
      result[i][j] = '${arr[j]}';
      path[i][j] = 1;
    } else {
      int bestSum = 0;
      int bestCount = 0;

      for (int k = 0; k < i; k++) {
        int partialSum = k * (j + 1) + (i - k) * (endIdx - j);
        int count = 0;

        for (int l = 0; l <= n - i + 1; l++) {
          if (partialSum + l * (endIdx - j) <= targetSum) {
            count++;
          }
        }

        if (count > bestCount) {
          bestCount = count;
          bestSum = partialSum;
        }
      }

      if (bestSum > 0) {
        result[i][j] = '$bestSum';
        path[i][j] = 2;
      } else {
        path[i][j] = 0;
      }
    }

    if (path[i][j] == 1) {
      partialSumArr[i][j] = bestSum;
    }

    solve(i + 1, j);
    solve(i, j + 1);
  }

  solve(1, 0);

  print(result);
  print(partialSumArr);
}

