void fn0() {
  List<int> arr = [1, 2, 3, 4, 5, 6, 7];
  int n = arr.length;
  List<List<int>> dp = List.generate(
    n + 1,
    (_) => List.filled(n + 1, 0),
  );

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= i; j++) {
      int total = 0;
      if (j == 0) {
        total = arr[i - 1];
      } else {
        List<int> sub = arr.sublist(j, i);
        for (int k = 0; k < sub.length; k++) {
          total += sub[k];
        }
      }
      dp[i][j] = total;
    }
  }

  List<List<int>> sums = [];
  List<int> paths = [];

  void backtrack(int i, int j, int sum) {
    if (i == n) {
      if (j == 0) {
        sums.add([sum]);
      } else {
        for (var p in paths) {
          sums.add([...p, sum]);
        }
      }
      return;
    }
    int option1 = dp[i + 1][j];
    int option2 = dp[i][j + 1];
    int option3 = dp[i + 1][j + 1];

    int maxVal = option1 > option2
        ? (option1 > option3 ? option1 : option3)
        : (option2 > option3 ? option2 : option3);

    if (maxVal == option1) {
      paths.add([option1]);
      backtrack(i + 1, j, sum + option1);
    }
    if (maxVal == option2) {
      backtrack(i, j + 1, sum + option2);
    }
    if (maxVal == option3) {
      backtrack(i + 1, j + 1, sum + option3);
    }
  }

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= i; j++) {
      if (dp[i][j] == 0) continue;
      backtrack(i, j, dp[i][j]);
    }
  }

  print(sums);
  print(paths);
}

