void fn0() {

  List<int> arr = [1, 2, 3, 4, 5, 6, 7];
  int n = arr.length;

  List<List<int>> dp = List.generate(n, (_) => List.filled(n, 0));

  for (int length = 2; length <= n; length++) {
    for (int start = 0; start + length <= n; start++) {
      int end = start + length - 1;
      int minCost = arr[start] + arr[end];

      for (int split = start + 1; split < end; split++) {
        int currentCost = arr[start] + arr[split] + arr[end];
        if (currentCost < minCost) {
          minCost = currentCost;
        }
      }

      dp[start][end] = minCost;
    }
  }

  List<List<int>> paths = List.generate(n, (_) => List.filled(n, 0));

  void printPath(List<int> path) {
    path.forEach((v) => print(v));
  }

  void generatePath(List<int> path, List<int> start, List<int> end) {
    path[start] = 1;
    if (start == end) {
      printPath(path);
    } else {
      for (int split = start + 1; split < end; split++) {
        if (dp[start][split] == dp[split][end]) {
          List<int> nextPath = List.from(path);
          generatePath(nextPath, start, split);
          generatePath(nextPath, split, end);
        }
      }
    }
  }

  for (int start = 0; start < n; start++) {
    for (int end = start + 1; end < n; end++) {
      if (dp[start][end] != 0) {
        List<int> path = List.filled(n, 0);
        generatePath(path, start, end);
      }
    }
  }
}

