List<int> fn0(List<int> votes) {
  List<int> counts = List.filled(2, 0);
  List<int> lastWinners = List.filled(2, -1);
  List<int> votesLeft = List<int>.from(votes);

  while (votesLeft.isNotEmpty) {
    int v = votesLeft.removeLast();
    int w = (v > 0) ? (v % 2 == 0) : (v == -1);
    if (w == 1) {
      counts[w]++;
      lastWinners[w] = v;
    } else {
      int a = w == 0 ? 1 : 2;
      int b = w == 0 ? 2 : 1;
      if (counts[a] == counts[b]) {
        int diffA = (v > 0) ? v.abs() : -v.abs();
        int diffB = (votes[lastWinners[a]!] > 0) ? votes[lastWinners[a]!].abs() : -votes[lastWinners[a]!].abs();
        if (diffA != diffB) {
          counts[w]++;
          lastWinners[w] = v;
        } else {
          if (counts[a] < counts[b]) {
            counts[w]++;
            lastWinners[w] = v;
          } else if (counts[a] > counts[b]) {
            counts[a]++;
          } else {
            counts[b]++;
          }
        }
      } else {
        counts[a]++;
      }
    }
  }

  return counts;
}

