Map<String, int> fn0(String dna, String pattern) {
  if (dna.isEmpty || pattern.isEmpty) {
    return {'hit': 0, 'loops': 0};
  }
  int n = dna.length;
  int m = pattern.length;
  List<List<int>> dp = List.generate(n + 1, (_) => List.filled(m + 1, 0));
  for (int i = 0; i <= n; i++) {
    dp[i][0] = i;
  }
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      int match = (i - 1 >= j - 1) ? 1 : 0;
      int deletions = (i - 1 >= j) ? dp[i - 1][j - 1] + 1 : dp[i - 1][0] + 1;
      int insertions = (i - 1 >= j - 1) ? dp[i - 1][j - 1] + 1 : dp[i - 1][0] + 1;
      int cost = match * 2 + deletions + insertions;
      dp[i][j] = dp[i - 1][j - 1] < cost
          ? dp[i - 1][j - 1]
          : dp[i - 1][0] < cost
              ? dp[i - 1][0]
              : dp[i][0];
      if (dp[i][j] == 0) {
        break;
      }
    }
  }
  int len = dp[n][m];
  int hits = len < m ? len : m;
  int loops = len == m ? hits : 0;
  return {'hit': hits, 'loops': loops};
}

