Map<String, int> fn0(List<List<int>> maze) {
  if (maze.isEmpty || maze[0].isEmpty) return {};
  int rows = maze.length;
  int cols = maze[0].length;
  int wallCount = 0;
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (maze[r][c] == 1) {
        wallCount++;
        dp[r][c] = 0;
      } else {
        if (r == 0 && c == 0) {
          dp[r][c] = 1;
        } else if (r == 0) {
          dp[r][c] = dp[r][c - 1] + 1;
        } else if (c == 0) {
          dp[r][c] = dp[r - 1][c] + 1;
        } else {
          int minVal = dp[r - 1][c] + 1;
          if (minVal < dp[r][c - 1] + 1) minVal = dp[r][c - 1] + 1;
          dp[r][c] = minVal;
        }
      }
    }
  }
  List<List<int>> dirs = [
    [-1, 0], [1, 0], [0, -1], [0, 1]
  ];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (dp[r][c] == 1) {
        List<List<int>> moves = [];
        for (List<int> d in dirs) {
          int nr = r + d[0];
          int nc = c + d[1];
          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && maze[nr][nc] == 0) {
            moves.add([nr, nc]);
          }
        }
        dp[r][c] = moves.length;
      }
    }
  }
  Map<String, int> result = {};
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      result[r + ',' + c] = dp[r][c];
    }
  }
  result['wallCount'] = wallCount;
  return result;
}

