class RandomSource {
  final int seed;
  final List<int> streams;

  RandomSource(this.seed) {
    streams = <int>[];
    for (int i = 0; i < 5; i++) {
      streams.add(seed);
    }
  }

  int next() {
    for (final stream in streams) {
      final next = Random(stream).nextInt(32);
      streams[streams.length - 1] = next;
      return next;
    }
  }
}

