void fn0() {

  final rand = Random(0);

  List<List<int>> squares = [
    [1, 2],
    [2, 3],
    [3, 4],
  ];

  List<int> moves = [0, 1, 2];

  int n = squares.length;

  List<List<bool>> visited = List.generate(
    n,
    (_) => List<bool>.filled(n, false),
  );

  List<List<int>> movesCount = List.generate(
    n,
    (_) => List<int>.filled(n, 0),
  );

  Set<List<int>> visitedSquares = {};

  void search(int row, int col, List<int> path) {
    if (row == n - 1 && col == n - 1) {
      path.add(0);
      visitedSquares.add(path);
      return;
    }

    if (row < 0 || row > n - 1 || col < 0 || col > n - 1) {
      return;
    }

    if (visited[row][col]) {
      return;
    }

    visited[row][col] = true;

    path.add(row * n + col);

    for (int m in moves) {
      int nr = row + m;
      int nc = col + m;

      if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
        search(nr, nc, path);
      }
    }

    path.removeLast();
    visited[row][col] = false;
  }

  for (int r = 0; r < n; r++) {
    for (int c = 0; c < n; c++) {
      if (!visited[r][c]) {
        List<int> path = [];
        search(r, c, path);
        for (int m in path) {
          movesCount[m % n][m ~/ n]++;
        }
      }
    }
  }

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (movesCount[i][j] > 0) {
        print('$i,$j:${movesCount[i][j]}');
      }
    }
  }

  for (var sq in visitedSquares) {
    print(sq);
  }
}

