void fn0() {

  const int rows = 8;
  const int cols = 8;

  final rng = Random(0);

  List<List<int>> board = List.generate(
    rows,
    (_) => List.generate(cols, (_) => rng.nextInt(2) == 0 ? 0 : rng.nextInt(2) == 1 ? 1 : -1),
  );

  List<List<int>> queens = [];

  bool isSafe(List<int> queen, int row, int col) {

    for (List<int> q in queens) {
      if (q[0] == row || q[1] == col) return false;
      if ((row - q[0]).abs() == (col - q[1]).abs()) return false;
    }
    return true;
  }

  void place(int row, int col) {
    if (row == queens.length) {

      queens.add([row, col]);
      return;
    }
    for (int c = 0; c < cols; c++) {
      if (isSafe(queens, row, c)) {
        place(row + 1, c);
      }
    }
  }

  void solve() {

    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        if (board[r][c] == 1) {
          place(0, c);
        }
      }
    }
  }

  void printBoard() {
    for (int i = 0; i < rows; i++) {
      String row = '';
      for (int j = 0; j < cols; j++) {
        row += board[i][j].toString();
      }
      print(row);
    }
    print('');
  }

  solve();

  printBoard();

  for (List<int> q in queens) {
    print(q[0], q[1]);
  }

  List<List<int>> boardCopy = List.from(board);
  List<List<int>> queensCopy = List.from(queens);

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (boardCopy[i][j] == 1) {
        List<List<int>> moves = [
          [i - 1, j],
          [i + 1, j],
          [i, j - 1],
          [i, j + 1],
          [i - 2, j - 1],
          [i - 2, j + 1],
          [i + 2, j - 1],
          [i + 2, j + 1],
        ];
        for (List<int> m in moves) {
          int ni = m[0], nj = m[1];
          if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
            if (isSafe(queensCopy, ni, nj)) {
              place(ni, nj);
              printBoard();
            }
          }
        }
      }
    }
  }
}

