      final tmp = arr[root];
      arr[root] = arr[largest];
      arr[largest] = tmp;
      heapify(arr, size, largest);
    }
  }

  for (int i = 0; i < nums.length; i++) {
    heapify(prefix, i + 1, i);
  }

  print(prefix);
}

