  List<int> index = 1;
  for (var value in data) {
    if (index >= data.length) break;
    if (value < 0) {
      index++;
      continue;
    }
    TreeNode node = TreeNode(value, []);
    root.children.add(node);
    if (index + 1 < data.length && data[index + 1] < 0) {
      index += 2;
    } else {
      index++;
    }
  }
  return root;
}

