    int r = t;
    int count = 0;
    while (r > 0) {
      count += (r % 6);
      r ~/= 6;
    }
    int rank = count;
    if (rank > 1) {
      int rankStr = rank.toString().padLeft(3, '0');
      totals[totals.length - 1 - count] = rankStr.codeUnitAt(0);
    }
  }
